window.ForXuanDiagram=function(q){const id=q.related||q.id;let svg='',caption='示意图，位置与长度以题目条件为准。';
const wrap=s=>'<svg class="plot" viewBox="0 0 420 270" role="img" aria-label="解题示意图"><g fill="none" stroke="#3b6554" stroke-width="2">'+s+'</g></svg>';
const text=(x,y,s)=>`<text x="${x}" y="${y}" fill="#3b6554" stroke="none" font-size="15" font-family="Georgia,Microsoft YaHei">${s}</text>`;
if(id==='c383-triangle'){svg=wrap('<path d="M50 210 116.67 135.46 350 210Z"/><path d="M116.67 135.46 200 210" stroke-dasharray="6 4"/><path d="M120 205v10m155-10v10"/>'+text(30,230,'B')+text(110,123,'A')+text(355,230,'C')+text(197,234,'D')+text(60,167,'c = 2')+text(240,157,'b = 2√6')+text(175,258,'a = 6')+text(163,168,'√5'));caption='正弦定理定比例 → 余弦定理补第三边 → 中线定尺度。D 是 BC 中点。';}
if(id==='c383-space'){svg=wrap('<path d="M210 25 55 215 350 215Z M210 25 275 140 350 215 M55 215 275 140"/><path d="M210 25 226.7 190 M55 215 226.7 190" stroke="#b78b40" stroke-dasharray="6 4"/>'+text(200,19,'O')+text(37,231,'A')+text(355,231,'B')+text(281,139,'C')+text(227,211,'H')+text(30,263,'OH ⊥ 平面 ABC；线面角 = ∠OAH'));caption='H 为底面等边三角形的中心，AH=s/√3、OA=s，故 cosθ=√3/3。';}
if(id==='c384-affine'){svg=wrap('<path d="M110 40 40 220 370 220Z M110 40 122.5 220 M40 220 214 112"/><circle cx="214" cy="112" r="3" fill="#3b6554"/>'+text(103,28,'A')+text(22,239,'B')+text(220,109,'C')+text(375,239,'D')+text(117,242,'E')+text(150,66,'AD = (5/2)AC')+text(27,266,'AE = (1−t)AB + tAD，t = 1/4'));caption='以 A 为共同起点，E 在线段 BD 上，仿射组合的两个系数相加为 1。';}
if(id==='c385-composite'){svg=wrap('<rect x="151" y="15" width="118" height="40" rx="7"/><path d="M210 55 75 100 M210 55 210 100 M210 55 345 100 M75 144v35 M210 144v35 M345 144v35"/>'+text(171,42,'−1 &lt; a &lt; 3')+text(38,127,'t₀ &lt; −1')+text(177,127,'−1 &lt; t₋ &lt; 1')+text(309,127,'1 &lt; t₊ &lt; 3')+text(49,205,'2 个原像')+text(182,205,'3 个原像')+text(316,205,'3 个原像')+text(92,252,'总数 = 2 + 3 + 3 = 8'));caption='先解 f(t)=a，再分别数 f(x)=t 的原像；临界参数 a=−1、3 必须另查。';}
if(id==='c386-hard'){svg=wrap('<path d="M35 135H385"/><path d="M135 127v16 M285 127v16"/>'+text(21,162,'−π/2')+text(128,162,'x₁')+text(278,162,'x₂')+text(379,162,'0')+text(65,94,'f′ &gt; 0')+text(183,94,'f′ &lt; 0')+text(310,94,'f′ &gt; 0')+text(85,204,'↗ 极大值 ↘ 极小值 ↗')+text(101,248,'a &gt; 2；x₁+x₂ = −π/2'));caption='只有 a>2 才有两不同负根。导数的“正、负、正”给出真正极值。';}
return svg?`<figure style="margin:18px 0">${svg}<figcaption class="snapshot">${caption}</figcaption></figure>`:'';
};
